
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers":
          "authorization, x-client-info, apikey, content-type",
            "Access-Control-Max-Age": "86400",
            };

            const MAX_REQUEST_BYTES = 100_000;
            const MAX_MESSAGES = 40;
            const MAX_CONTENT_LENGTH = 12_000;
            const MAX_OUTPUT_TOKENS = 900;

            type ChatMessage = {
              role: "user" | "assistant";
                content: string;
                };

                function isRecord(value: unknown): value is Record<string, unknown> {
                  return typeof value === "object" && value !== null && !Array.isArray(value);
                  }

                  function jsonResponse(
                    body: Record<string, unknown>,
                      status = 200,
                      ): Response {
                        return new Response(JSON.stringify(body), {
                            status,
                                headers: {
                                      ...corsHeaders,
                                            "Content-Type": "application/json; charset=utf-8",
                                                },
                                                  });
                                                  }

                                                  Deno.serve(async (req: Request) => {
                                                    if (req.method === "OPTIONS") {
                                                        return new Response(null, {
                                                              status: 204,
                                                                    headers: corsHeaders,
                                                                        });
                                                                          }

                                                                            if (req.method !== "POST") {
                                                                                return jsonResponse({ error: "Método não permitido." }, 405);
                                                                                  }

                                                                                    try {
                                                                                        const rawBody = await req.text();

                                                                                            if (
                                                                                                  new TextEncoder().encode(rawBody).byteLength >
                                                                                                        MAX_REQUEST_BYTES
                                                                                                            ) {
                                                                                                                  return jsonResponse({
                                                                                                                          error: "A solicitação excede o tamanho permitido.",
                                                                                                                                }, 413);
                                                                                                                                    }

                                                                                                                                        let body: unknown;

                                                                                                                                            try {
                                                                                                                                                  body = JSON.parse(rawBody);
                                                                                                                                                      } catch {
                                                                                                                                                            return jsonResponse({
                                                                                                                                                                    error: "O corpo da solicitação deve ser um JSON válido.",
                                                                                                                                                                          }, 400);
                                                                                                                                                                              }

                                                                                                                                                                                  if (!isRecord(body) || !Array.isArray(body.messages)) {
                                                                                                                                                                                        return jsonResponse({
                                                                                                                                                                                                error: 'Envie um campo "messages" com uma lista de mensagens.',
                                                                                                                                                                                                      }, 400);
                                                                                                                                                                                                          }

                                                                                                                                                                                                              const rawMessages = body.messages;

                                                                                                                                                                                                                  if (
                                                                                                                                                                                                                        rawMessages.length === 0 ||
                                                                                                                                                                                                                              rawMessages.length > MAX_MESSAGES
                                                                                                                                                                                                                                  ) {
                                                                                                                                                                                                                                        return jsonResponse({
                                                                                                                                                                                                                                                error: `Envie de 1 a ${MAX_MESSAGES} mensagens.`,
                                                                                                                                                                                                                                                      }, 400);
                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                              const messages: ChatMessage[] = [];

                                                                                                                                                                                                                                                                  for (const item of rawMessages) {
                                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                                !isRecord(item) ||
                                                                                                                                                                                                                                                                                        (item.role !== "user" && item.role !== "assistant") ||
                                                                                                                                                                                                                                                                                                typeof item.content !== "string" ||
                                                                                                                                                                                                                                                                                                        item.content.trim().length === 0 ||
                                                                                                                                                                                                                                                                                                                item.content.length > MAX_CONTENT_LENGTH
                                                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                                              return jsonResponse({
                                                                                                                                                                                                                                                                                                                                        error: "Cada mensagem deve ter um papel e conteúdo válidos.",
                                                                                                                                                                                                                                                                                                                                                }, 400);
                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                            messages.push({
                                                                                                                                                                                                                                                                                                                                                                    role: item.role,
                                                                                                                                                                                                                                                                                                                                                                            content: item.content,
                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                          if (messages[messages.length - 1].role !== "user") {
                                                                                                                                                                                                                                                                                                                                                                                                return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                        error: "A última mensagem deve ser do usuário.",
                                                                                                                                                                                                                                                                                                                                                                                                              }, 400);
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                      const apiToken = Deno.env.get("CLOUDFLARE_API_TOKEN");
                                                                                                                                                                                                                                                                                                                                                                                                                          const accountId = Deno.env.get("CLOUDFLARE_ACCOUNT_ID");

                                                                                                                                                                                                                                                                                                                                                                                                                              if (!apiToken || !accountId) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                            error: "A função não está configurada corretamente.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                          const model = "@cf/zai-org/glm-4.7-flash";

                                                                                                                                                                                                                                                                                                                                                                                                                                                              const cloudflareUrl =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(accountId)}/ai/run/${model}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let upstream: Response;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  upstream = await fetch(cloudflareUrl, {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Authorization": `Bearer ${apiToken}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Content-Type": "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                messages: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          role: "system",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        content:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Você é a OSVYRA, uma assistente de inteligência artificial. Responda sempre em português brasileiro. Use uma personalidade profissional, natural, séria e elegante. Ajude com criação, negócios, produtividade e conhecimentos gerais. Forneça somente a resposta final ao usuário, sem apresentar planejamento ou raciocínio interno.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ...messages,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    max_completion_tokens: MAX_OUTPUT_TOKENS,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              temperature: 0.4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error: "Não foi possível conectar ao serviço de IA.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!upstream.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error: "O serviço de IA não conseguiu processar a solicitação.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let result: unknown;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  result = await upstream.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    error: "O serviço de IA retornou uma resposta inválida.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const answer =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        isRecord(result) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              isRecord(result.result) &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    typeof result.result.response === "string"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? result.result.response.trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!answer) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "O serviço de IA não retornou uma resposta válida.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return jsonResponse({ answer });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return jsonResponse({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                error: "Ocorreu um erro ao processar a solicitação.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      